#!/usr/bin/env bash
# Writes ios/Local.xcconfig (git-ignored) so a Debug build on a phone talks to the dev server on this Mac's LAN IP.
set -euo pipefail
cd "$(dirname "$0")/.."
PORT="${PORT:-18090}"
ip=""
for i in en0 en1 en2 en3 en4 en5 en6; do ip="$(ipconfig getifaddr "$i" 2>/dev/null || true)"; [ -n "$ip" ] && break; done
[ -n "$ip" ] || { echo "No Wi-Fi/Ethernet address found. Join the same Wi-Fi as the phone and retry." >&2; exit 1; }
cat > ios/Local.xcconfig <<EOF
// Generated by make ios-local-config. Git-ignored. Re-run when the Mac's IP changes.
INBOX_DEV_API_BASE_URL = http:/\$()/$ip:$PORT
INBOX_DEV_TOKEN = dev-token-inbox-local-0000
EOF
echo "Wrote ios/Local.xcconfig for http://$ip:$PORT"
